    """Decode jq's accepted non-standard numeric constants."""
    return {"NaN": float("nan"), "nan": float("nan"),
            "Infinity": float("inf"), "infinite": float("inf"),
            "-Infinity": float("-inf"), "-infinite": float("-inf"),
            "-NaN": float("nan"), "-nan": float("nan")} [value]
